    ON business_record_identifiers;
DROP FUNCTION IF EXISTS enforce_primary_business_identifier_unique();
DROP INDEX IF EXISTS idx_business_identifier_lookup;

changeSet.sql:
CREATE OR REPLACE FUNCTION validate_primary_business_identifier_definition()
RETURNS trigger AS $$
DECLARE
    duplicate_value VARCHAR(512);
BEGIN
    IF NEW.primary_flag = TRUE AND NEW.active_flag = TRUE THEN
        SELECT bri.normalized_value
          INTO duplicate_value
          FROM business_record_identifiers bri
         WHERE bri.tenant_id = NEW.tenant_id
           AND bri.definition_id = NEW.id
         GROUP BY bri.normalized_value
        HAVING COUNT(*) > 1
         LIMIT 1;

        IF duplicate_value IS NOT NULL THEN
            RAISE EXCEPTION 'Identifier definition cannot become Primary because existing values are not unique'
                USING ERRCODE = '23505',
                      CONSTRAINT = 'uq_business_primary_identifier_value';
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_business_identifier_definition_primary_unique
    ON business_identifier_definitions;
CREATE TRIGGER trg_business_identifier_definition_primary_unique
    BEFORE INSERT OR UPDATE OF primary_flag, active_flag
    ON business_identifier_definitions
    FOR EACH ROW
    EXECUTE FUNCTION validate_primary_business_identifier_definition();

